const express = require('express');
const router = express.Router();
const store = require('../data/store');

/**
 * POST /api/auth/login
 * Body: { role: 'maintenance_engineer' | 'operations_manager' | 'administrator' }
 * Returns the matching mock user (no real passwords — demo mode).
 */
router.post('/login', (req, res) => {
  const { role } = req.body;
  if (!role) return res.status(400).json({ error: 'role is required' });

  const user = store.users.find(u => u.role === role);
  if (!user) return res.status(404).json({ error: `No user with role: ${role}` });

  res.json({ user });
});

/**
 * GET /api/auth/me
 * In a real system this would validate a JWT. Here it just returns users list
 * so the frontend can pick a demo identity.
 */
router.get('/users', (_req, res) => {
  res.json(store.users);
});

module.exports = router;

const express = require('express');
const router = express.Router();
const store = require('../data/store');

// GET /api/assets
router.get('/', (_req, res) => {
  res.json(store.assets);
});

// GET /api/assets/:id
router.get('/:id', (req, res) => {
  const asset = store.assets.find(a => a.id === req.params.id);
  if (!asset) return res.status(404).json({ error: 'Asset not found' });
  res.json(asset);
});

// PATCH /api/assets/:id
router.patch('/:id', (req, res) => {
  const idx = store.assets.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Asset not found' });
  store.assets[idx] = { ...store.assets[idx], ...req.body };
  res.json(store.assets[idx]);
});

module.exports = router;

const express = require('express');
const router = express.Router();
const store = require('../data/store');

// GET /api/sensors
// Optional query: ?assetId=B12
router.get('/', (req, res) => {
  const { assetId } = req.query;
  const result = assetId
    ? store.sensors.filter(s => s.assetId === assetId)
    : store.sensors;
  res.json(result);
});

// GET /api/sensors/:id
router.get('/:id', (req, res) => {
  const sensor = store.sensors.find(s => s.id === req.params.id);
  if (!sensor) return res.status(404).json({ error: 'Sensor not found' });
  res.json(sensor);
});

// PATCH /api/sensors/:id
router.patch('/:id', (req, res) => {
  const idx = store.sensors.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Sensor not found' });
  store.sensors[idx] = { ...store.sensors[idx], ...req.body };
  res.json(store.sensors[idx]);
});

// GET /api/sensors/:id/readings
router.get('/:id/readings', (req, res) => {
  const result = store.readings.filter(r => r.sensorId === req.params.id);
  res.json(result);
});

module.exports = router;

const express = require('express');
const router = express.Router();
const store = require('../data/store');

// GET /api/alerts
// Optional query: ?assetId=B12&status=active
router.get('/', (req, res) => {
  let result = store.alerts;
  if (req.query.assetId) result = result.filter(a => a.assetId === req.query.assetId);
  if (req.query.status)  result = result.filter(a => a.status  === req.query.status);
  res.json(result);
});

// GET /api/alerts/:id
router.get('/:id', (req, res) => {
  const alert = store.alerts.find(a => a.id === req.params.id);
  if (!alert) return res.status(404).json({ error: 'Alert not found' });
  res.json(alert);
});

// POST /api/alerts  — create a new alert (used by demo mode)
router.post('/', (req, res) => {
  const alert = req.body;
  if (!alert.id || !alert.assetId || !alert.title) {
    return res.status(400).json({ error: 'id, assetId, and title are required' });
  }
  store.alerts.unshift(alert);
  res.status(201).json(alert);
});

// PATCH /api/alerts/:id/acknowledge
router.patch('/:id/acknowledge', (req, res) => {
  const idx = store.alerts.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Alert not found' });
  const { by } = req.body;
  store.alerts[idx] = {
    ...store.alerts[idx],
    status: 'acknowledged',
    acknowledgedAt: new Date().toISOString(),
    acknowledgedBy: by ?? 'Unknown',
  };
  res.json(store.alerts[idx]);
});

// PATCH /api/alerts/:id/resolve
router.patch('/:id/resolve', (req, res) => {
  const idx = store.alerts.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Alert not found' });
  store.alerts[idx] = {
    ...store.alerts[idx],
    status: 'resolved',
    resolvedAt: new Date().toISOString(),
  };
  res.json(store.alerts[idx]);
});

module.exports = router;

const express = require('express');
const router = express.Router();
const store = require('../data/store');

// GET /api/work-orders
// Optional query: ?assetId=B12&status=open
router.get('/', (req, res) => {
  let result = store.workOrders;
  if (req.query.assetId) result = result.filter(w => w.assetId === req.query.assetId);
  if (req.query.status)  result = result.filter(w => w.status  === req.query.status);
  res.json(result);
});

// GET /api/work-orders/:id
router.get('/:id', (req, res) => {
  const wo = store.workOrders.find(w => w.id === req.params.id);
  if (!wo) return res.status(404).json({ error: 'Work order not found' });
  res.json(wo);
});

// POST /api/work-orders — create
router.post('/', (req, res) => {
  const wo = { ...req.body, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
  if (!wo.id || !wo.assetId || !wo.title) {
    return res.status(400).json({ error: 'id, assetId, and title are required' });
  }
  store.workOrders.unshift(wo);
  res.status(201).json(wo);
});

// PATCH /api/work-orders/:id — update status, notes, assignee, etc.
router.patch('/:id', (req, res) => {
  const idx = store.workOrders.findIndex(w => w.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Work order not found' });
  store.workOrders[idx] = {
    ...store.workOrders[idx],
    ...req.body,
    updatedAt: new Date().toISOString(),
  };
  res.json(store.workOrders[idx]);
});

module.exports = router;

