/**
 * Thin fetch wrapper for the Express API.
 * All requests go to /api/* — Vite proxies them to http://localhost:3001 in dev.
 * In production the Express server serves the built frontend too, so the same
 * origin works without any proxy.
 */

const BASE = '/api';

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({ error: res.statusText }));
    throw new Error(err.error ?? `HTTP ${res.status}`);
  }
  return res.json() as Promise<T>;
}

// ── Auth ───────────────────────────────────────────────────────────────────
export const authApi = {
  login: (role: string) =>
    request<{ user: import('../types').User }>('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ role }),
    }),
  listUsers: () =>
    request<import('../types').User[]>('/auth/users'),
};

// ── Assets ─────────────────────────────────────────────────────────────────
export const assetsApi = {
  list: () =>
    request<import('../types').Asset[]>('/assets'),
  get: (id: string) =>
    request<import('../types').Asset>(`/assets/${id}`),
  patch: (id: string, patch: Partial<import('../types').Asset>) =>
    request<import('../types').Asset>(`/assets/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(patch),
    }),
};

// ── Sensors ────────────────────────────────────────────────────────────────
export const sensorsApi = {
  list: (assetId?: string) =>
    request<import('../types').Sensor[]>(assetId ? `/sensors?assetId=${assetId}` : '/sensors'),
  get: (id: string) =>
    request<import('../types').Sensor>(`/sensors/${id}`),
  patch: (id: string, patch: Partial<import('../types').Sensor>) =>
    request<import('../types').Sensor>(`/sensors/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(patch),
    }),
  readings: (id: string) =>
    request<import('../types').SensorReading[]>(`/sensors/${id}/readings`),
};

// ── Alerts ─────────────────────────────────────────────────────────────────
export const alertsApi = {
  list: (params?: { assetId?: string; status?: string }) => {
    const q = new URLSearchParams(params as Record<string, string>).toString();
    return request<import('../types').Alert[]>(`/alerts${q ? '?' + q : ''}`);
  },
  create: (alert: import('../types').Alert) =>
    request<import('../types').Alert>('/alerts', {
      method: 'POST',
      body: JSON.stringify(alert),
    }),
  acknowledge: (id: string, by: string) =>
    request<import('../types').Alert>(`/alerts/${id}/acknowledge`, {
      method: 'PATCH',
      body: JSON.stringify({ by }),
    }),
  resolve: (id: string) =>
    request<import('../types').Alert>(`/alerts/${id}/resolve`, {
      method: 'PATCH',
      body: JSON.stringify({}),
    }),
};

// ── Work Orders ────────────────────────────────────────────────────────────
export const workOrdersApi = {
  list: (params?: { assetId?: string; status?: string }) => {
    const q = new URLSearchParams(params as Record<string, string>).toString();
    return request<import('../types').WorkOrder[]>(`/work-orders${q ? '?' + q : ''}`);
  },
  create: (wo: import('../types').WorkOrder) =>
    request<import('../types').WorkOrder>('/work-orders', {
      method: 'POST',
      body: JSON.stringify(wo),
    }),
  patch: (id: string, patch: Partial<import('../types').WorkOrder>) =>
    request<import('../types').WorkOrder>(`/work-orders/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(patch),
    }),
};

// ── Predictions ────────────────────────────────────────────────────────────
export const predictionsApi = {
  list: (assetId?: string) =>
    request<import('../types').Prediction[]>(assetId ? `/predictions?assetId=${assetId}` : '/predictions'),
};

// ── Maintenance records ────────────────────────────────────────────────────
export const maintenanceApi = {
  list: (assetId?: string) =>
    request<import('../types').MaintenanceRecord[]>(assetId ? `/maintenance?assetId=${assetId}` : '/maintenance'),
};

// ── Network ────────────────────────────────────────────────────────────────
export const networkApi = {
  lines: () =>
    request<import('../types').RailwayLine[]>('/network/lines'),
  stations: () =>
    request<import('../types').Station[]>('/network/stations'),
};

import {
  createContext, useContext, useState, useCallback, useEffect,
  type ReactNode,
} from 'react';
import type { Asset, Sensor, Alert, WorkOrder } from '../types';
import { assetsApi, sensorsApi, alertsApi, workOrdersApi } from '../lib/api';

// Fallback to local mock data if the API is unavailable (e.g. static preview)
import { MOCK_ASSETS }      from '../data/assets';
import { MOCK_SENSORS }     from '../data/sensors';
import { MOCK_ALERTS }      from '../data/alerts';
import { MOCK_WORK_ORDERS } from '../data/workOrders';

interface AssetContextValue {
  assets: Asset[];
  sensors: Sensor[];
  alerts: Alert[];
  workOrders: WorkOrder[];
  loading: boolean;

  selectedAsset: Asset | null;
  selectedSensor: Sensor | null;

  selectAsset: (assetId: string | null) => void;
  selectSensor: (sensorId: string | null) => void;

  updateSensor: (sensorId: string, patch: Partial<Sensor>) => void;
  updateAsset: (assetId: string, patch: Partial<Asset>) => void;
  addAlert: (alert: Alert) => void;
  addWorkOrder: (wo: WorkOrder) => void;
  updateWorkOrder: (workOrderId: string, patch: Partial<WorkOrder>) => void;
  acknowledgeAlert: (alertId: string, by: string) => void;
  resolveAlert: (alertId: string) => void;
}

const AssetContext = createContext<AssetContextValue | null>(null);

export function AssetProvider({ children }: { children: ReactNode }) {
  const [assets,     setAssets]     = useState<Asset[]>(MOCK_ASSETS);
  const [sensors,    setSensors]    = useState<Sensor[]>(MOCK_SENSORS);
  const [alerts,     setAlerts]     = useState<Alert[]>(MOCK_ALERTS);
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [loading,    setLoading]    = useState(true);

  const [selectedAssetId,  setSelectedAssetId]  = useState<string | null>(null);
  const [selectedSensorId, setSelectedSensorId] = useState<string | null>(null);

  // ── Bootstrap: load everything from the API ──────────────────────────────
  useEffect(() => {
    let cancelled = false;
    Promise.all([
      assetsApi.list(),
      sensorsApi.list(),
      alertsApi.list(),
      workOrdersApi.list(),
    ])
      .then(([a, s, al, wo]) => {
        if (cancelled) return;
        setAssets(a);
        setSensors(s);
        setAlerts(al);
        setWorkOrders(wo);
      })
      .catch(() => {
        // API unreachable — keep the pre-loaded mock data as fallback
        console.warn('[regen] API unreachable, using local mock data');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  // ── Derived selections ───────────────────────────────────────────────────
  const selectedAsset  = assets.find(a => a.id === selectedAssetId)   ?? null;
  const selectedSensor = sensors.find(s => s.id === selectedSensorId) ?? null;

  // ── Selection ────────────────────────────────────────────────────────────
  const selectAsset = useCallback((assetId: string | null) => {
    setSelectedAssetId(assetId);
    if (!assetId) setSelectedSensorId(null);
  }, []);

  const selectSensor = useCallback((sensorId: string | null) => {
    setSelectedSensorId(sensorId);
    if (sensorId) {
      const sensor = sensors.find(s => s.id === sensorId);
      if (sensor) setSelectedAssetId(sensor.assetId);
    }
  }, [sensors]);

  // ── Mutations — optimistic local update + fire-and-forget to API ─────────
  const updateSensor = useCallback((sensorId: string, patch: Partial<Sensor>) => {
    setSensors(prev => prev.map(s => s.id === sensorId ? { ...s, ...patch } : s));
    sensorsApi.patch(sensorId, patch).catch(() => {/* demo: ignore errors */});
  }, []);

  const updateAsset = useCallback((assetId: string, patch: Partial<Asset>) => {
    setAssets(prev => prev.map(a => a.id === assetId ? { ...a, ...patch } : a));
    assetsApi.patch(assetId, patch).catch(() => {});
  }, []);

  const addAlert = useCallback((alert: Alert) => {
    setAlerts(prev => [alert, ...prev]);
    alertsApi.create(alert).catch(() => {});
  }, []);

  const addWorkOrder = useCallback((wo: WorkOrder) => {
    setWorkOrders(prev => [wo, ...prev]);
    workOrdersApi.create(wo).catch(() => {});
  }, []);

  const updateWorkOrder = useCallback((workOrderId: string, patch: Partial<WorkOrder>) => {
    setWorkOrders(prev =>
      prev.map(wo => wo.id === workOrderId
        ? { ...wo, ...patch, updatedAt: new Date().toISOString() }
        : wo
      )
    );
    workOrdersApi.patch(workOrderId, patch).catch(() => {});
  }, []);

  const acknowledgeAlert = useCallback((alertId: string, by: string) => {
    setAlerts(prev =>
      prev.map(a => a.id === alertId ? {
        ...a,
        status: 'acknowledged' as const,
        acknowledgedAt: new Date().toISOString(),
        acknowledgedBy: by,
      } : a)
    );
    alertsApi.acknowledge(alertId, by).catch(() => {});
  }, []);

  const resolveAlert = useCallback((alertId: string) => {
    setAlerts(prev =>
      prev.map(a => a.id === alertId ? {
        ...a,
        status: 'resolved' as const,
        resolvedAt: new Date().toISOString(),
      } : a)
    );
    alertsApi.resolve(alertId).catch(() => {});
  }, []);

  return (
    <AssetContext.Provider value={{
      assets, sensors, alerts, workOrders, loading,
      selectedAsset, selectedSensor,
      selectAsset, selectSensor,
      updateSensor, updateAsset,
      addAlert, addWorkOrder, updateWorkOrder,
      acknowledgeAlert, resolveAlert,
    }}>
      {children}
    </AssetContext.Provider>
  );
}

export function useAssets() {
  const ctx = useContext(AssetContext);
  if (!ctx) throw new Error('useAssets must be used within AssetProvider');
  return ctx;
}

import { createContext, useContext, useState, type ReactNode } from 'react';
import type { User, Role } from '../types';
import { authApi } from '../lib/api';
import { MOCK_USERS } from '../data/users';

interface AuthContextValue {
  user: User | null;
  login: (role: Role) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);

  const login = async (role: Role) => {
    try {
      const { user: apiUser } = await authApi.login(role);
      setUser(apiUser);
    } catch {
      // API unreachable — fall back to local mock user
      const found = MOCK_USERS.find(u => u.role === role) ?? MOCK_USERS[0];
      setUser(found);
    }
  };

  const logout = () => setUser(null);

  return (
    <AuthContext.Provider value={{ user, login, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

