                <td className="px-4 py-3">
                  <span className="flex items-center gap-1.5 text-green">
                    <span className="w-1.5 h-1.5 rounded-full bg-green" />
                    Active
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

