const express = require('express');
const router  = express.Router();
const store   = require('../data/store');
const { fetchAll, updateRows } = require('../lib/supabase');

// GET /api/assets
router.get('/', async (_req, res) => {
  const rows = await fetchAll('assets');
  res.json(rows && rows.length ? rows : store.assets);
});

// GET /api/assets/:id
router.get('/:id', async (req, res) => {
  const rows = await fetchAll('assets', { filter: { id: req.params.id } });
  if (rows && rows.length) return res.json(rows[0]);
  const asset = store.assets.find(a => a.id === req.params.id);
  if (!asset) return res.status(404).json({ error: 'Asset not found' });
  res.json(asset);
});

// PATCH /api/assets/:id  — optimistic update: store + Supabase
router.patch('/:id', async (req, res) => {
  // Update in-memory store
  const idx = store.assets.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Asset not found' });
  store.assets[idx] = { ...store.assets[idx], ...req.body };

  // Persist to Supabase (best-effort)
  await updateRows('assets', { id: req.params.id }, req.body);

  res.json(store.assets[idx]);
});

module.exports = router;

const express = require('express');
const router  = express.Router();
const store   = require('../data/store');
const { fetchAll, updateRows } = require('../lib/supabase');

// GET /api/sensors  — optional ?assetId=B12
router.get('/', async (req, res) => {
  const opts = req.query.assetId
    ? { filter: { asset_id: req.query.assetId } }
    : {};
  const rows = await fetchAll('sensors', opts);

  if (rows && rows.length) {
    // Supabase uses snake_case columns — normalise to camelCase for the frontend
    return res.json(rows.map(normaliseSensor));
  }

  // Fallback
  const result = req.query.assetId
    ? store.sensors.filter(s => s.assetId === req.query.assetId)
    : store.sensors;
  res.json(result);
});

// GET /api/sensors/:id
router.get('/:id', async (req, res) => {
  const rows = await fetchAll('sensors', { filter: { id: req.params.id } });
  if (rows && rows.length) return res.json(normaliseSensor(rows[0]));
  const sensor = store.sensors.find(s => s.id === req.params.id);
  if (!sensor) return res.status(404).json({ error: 'Sensor not found' });
  res.json(sensor);
});

// PATCH /api/sensors/:id
router.patch('/:id', async (req, res) => {
  const idx = store.sensors.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Sensor not found' });
  store.sensors[idx] = { ...store.sensors[idx], ...req.body };

  // Map camelCase → snake_case for Supabase
  const patch = toSnake(req.body);
  await updateRows('sensors', { id: req.params.id }, patch);

  res.json(store.sensors[idx]);
});

// GET /api/sensors/:id/readings
router.get('/:id/readings', async (req, res) => {
  const rows = await fetchAll('sensor_readings', {
    filter: { sensor_id: req.params.id },
    order: { col: 'timestamp', asc: true },
  });
  if (rows && rows.length) {
    return res.json(rows.map(r => ({
      id:        r.id,
      sensorId:  r.sensor_id,
      value:     r.value,
      timestamp: r.timestamp,
      severity:  r.severity,
    })));
  }
  res.json(store.readings.filter(r => r.sensorId === req.params.id));
});

// ── Helpers ────────────────────────────────────────────────────────────────
function normaliseSensor(r) {
  return {
    id:           r.id,
    assetId:      r.asset_id      ?? r.assetId,
    name:         r.name,
    type:         r.type,
    unit:         r.unit,
    status:       r.status,
    severity:     r.severity,
    currentValue: r.current_value ?? r.currentValue,
    normalMin:    r.normal_min    ?? r.normalMin,
    normalMax:    r.normal_max    ?? r.normalMax,
    warningMax:   r.warning_max   ?? r.warningMax,
    criticalMax:  r.critical_max  ?? r.criticalMax,
    lastUpdate:   r.last_update   ?? r.lastUpdate,
    mapX:         r.map_x         ?? r.mapX,
    mapY:         r.map_y         ?? r.mapY,
  };
}

function toSnake(obj) {
  const map = {
    assetId: 'asset_id', currentValue: 'current_value', normalMin: 'normal_min',
    normalMax: 'normal_max', warningMax: 'warning_max', criticalMax: 'critical_max',
    lastUpdate: 'last_update', mapX: 'map_x', mapY: 'map_y',
  };
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    out[map[k] || k] = v;
  }
  return out;
}

module.exports = router;

const express = require('express');
const router  = express.Router();
const store   = require('../data/store');
const { fetchAll, insertRow, updateRows } = require('../lib/supabase');

// GET /api/alerts  — optional ?assetId=B12&status=active
router.get('/', async (req, res) => {
  const opts = {};
  if (req.query.assetId) opts.filter = { ...(opts.filter || {}), asset_id: req.query.assetId };
  if (req.query.status)  opts.filter = { ...(opts.filter || {}), status: req.query.status };

  const rows = await fetchAll('alerts', opts);
  if (rows && rows.length) return res.json(rows.map(normaliseAlert));

  // Fallback
  let result = store.alerts;
  if (req.query.assetId) result = result.filter(a => a.assetId === req.query.assetId);
  if (req.query.status)  result = result.filter(a => a.status  === req.query.status);
  res.json(result);
});

// GET /api/alerts/:id
router.get('/:id', async (req, res) => {
  const rows = await fetchAll('alerts', { filter: { id: req.params.id } });
  if (rows && rows.length) return res.json(normaliseAlert(rows[0]));
  const alert = store.alerts.find(a => a.id === req.params.id);
  if (!alert) return res.status(404).json({ error: 'Alert not found' });
  res.json(alert);
});

// POST /api/alerts
router.post('/', async (req, res) => {
  const alert = req.body;
  if (!alert.id || !alert.assetId || !alert.title)
    return res.status(400).json({ error: 'id, assetId, and title are required' });

  store.alerts.unshift(alert);

  await insertRow('alerts', {
    id:          alert.id,
    asset_id:    alert.assetId,
    sensor_id:   alert.sensorId   || null,
    title:       alert.title,
    description: alert.description,
    severity:    alert.severity,
    status:      alert.status,
    created_at:  alert.createdAt  || new Date().toISOString(),
  });

  res.status(201).json(alert);
});

// PATCH /api/alerts/:id/acknowledge
router.patch('/:id/acknowledge', async (req, res) => {
  const idx = store.alerts.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Alert not found' });

  const now = new Date().toISOString();
  const by  = req.body.by ?? 'Unknown';
  store.alerts[idx] = { ...store.alerts[idx], status: 'acknowledged', acknowledgedAt: now, acknowledgedBy: by };

  await updateRows('alerts', { id: req.params.id }, {
    status: 'acknowledged', acknowledged_at: now, acknowledged_by: by,
  });

  res.json(store.alerts[idx]);
});

// PATCH /api/alerts/:id/resolve
router.patch('/:id/resolve', async (req, res) => {
  const idx = store.alerts.findIndex(a => a.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Alert not found' });

  const now = new Date().toISOString();
  store.alerts[idx] = { ...store.alerts[idx], status: 'resolved', resolvedAt: now };

  await updateRows('alerts', { id: req.params.id }, { status: 'resolved', resolved_at: now });

  res.json(store.alerts[idx]);
});

// ── Helper ─────────────────────────────────────────────────────────────────
function normaliseAlert(r) {
  return {
    id:             r.id,
    assetId:        r.asset_id        ?? r.assetId,
    sensorId:       r.sensor_id       ?? r.sensorId,
    title:          r.title,
    description:    r.description,
    severity:       r.severity,
    status:         r.status,
    createdAt:      r.created_at      ?? r.createdAt,
    acknowledgedAt: r.acknowledged_at ?? r.acknowledgedAt,
    acknowledgedBy: r.acknowledged_by ?? r.acknowledgedBy,
    resolvedAt:     r.resolved_at     ?? r.resolvedAt,
  };
}

module.exports = router;

